import re
import copy
from .file_logger import FileLogger


class PingAnalyzer(object):
    DEFAULT_STATISTICS = {'drop': [],
                          'latency_avg': None,
                          'packet_loss': 0.0,
                          'latency_min': None,
                          'latency_max': None
                          }

    def __init__(self, logger, **kwargs):
        """Ping Analyzer"""
        self.logger = self._get_logger(logger)
        self.start_step = kwargs.get('start_step') if 'start_step' in kwargs else 5
        self.threshold = kwargs.get('threshold') if 'threshold' in kwargs else 1.00
        self.lines_to_log_after_drop = kwargs.get('lines_to_log_after_drop') if 'lines_to_log_after_drop' in kwargs else 10

        self.drops_count = 0
        self.statistics = copy.deepcopy(self.DEFAULT_STATISTICS)

        self.request_sent = 0

        self.current_latency = 0.0
        self.previous_latency = 0.0
        self.current_line = ""
        self.previous_line = ""
        self.line_number = -2  # -2 value for skipping ping initialization, counting only lines with data
        self.packet_loss = 0

    def append_log_line(self, line):
        """Append log line"""
        self.previous_line = self.current_line
        self.current_line = line

        self.logger.info(line + '\n')

        self.line_number += 1

        self.recalculate_statistics()
        self.analyze_latency_variations()

    def recalculate_statistics(self):
        """Recalculate statistics"""
        self.previous_latency = self.current_latency
        self.current_latency = self.extract_latency(self.current_line)

        if self.line_number <= self.start_step or not self.current_line:
            return

        if self.current_latency != 0:
            self.request_sent += 1
        else:
            self.packet_loss += 1
            self.statistics['packet_loss'] = float(self.packet_loss) * 100 / float(self.request_sent + self.packet_loss)
            return

        if not self.statistics.get('latency_min'):
            self.statistics['latency_min'] = self.statistics['latency_max'] = self.statistics[
                'latency_avg'] = self.current_latency
        else:
            if self.current_latency < self.statistics['latency_min']:
                self.statistics['latency_min'] = self.current_latency
            if self.current_latency > self.statistics['latency_max']:
                self.statistics['latency_max'] = self.current_latency

            self.statistics['latency_avg'] = float(((self.request_sent - self.statistics['packet_loss'] - 1) * (
                self.statistics['latency_avg'] or 0)) + self.current_latency) / float(
                self.request_sent - self.statistics['packet_loss']) if (self.request_sent - self.statistics['packet_loss']) else 0

    def get_results(self):
        """Get results"""
        if self.statistics.get('latency_avg'):
            self.statistics['latency_avg'] = round(self.statistics['latency_avg'], 2)
        if self.statistics.get('packet_loss'):
            self.statistics['packet_loss'] = round(self.statistics['packet_loss'], 2)
        self.append_current_statistics()
        return self.statistics

    def reset_statistics(self):
        """Reset statistics"""
        self.logger.info("Statistics reset called, performing statistics dump\n")
        self.append_current_statistics()

        self.statistics = copy.deepcopy(self.DEFAULT_STATISTICS)
        self.request_sent = 0
        self.drops_count = 0

    def append_current_statistics(self):
        """Append current statistics"""
        if self.statistics.get('latency_avg'):
            self.statistics['latency_avg'] = round(self.statistics['latency_avg'], 2)
        if self.statistics.get('packet_loss'):
            self.statistics['packet_loss'] = round(self.statistics['packet_loss'], 2)

        line = """Data transfer statistics: latency min: %s ms | max: %s ms | Average: %s ms | Packet loss: %s%%
                  Observed drops: %s """ % \
               (self.statistics.get("latency_min", 0),
                self.statistics["latency_max"],
                self.statistics["latency_avg"],
                self.statistics["packet_loss"],
                self.statistics["drop"])
        # self.log_file.write(line)
        self.logger.info(line)

    @staticmethod
    def extract_latency(log_line):
        """Extract latency from log line matching: Reply from 10.135.47.3: bytes=32 time=78 ms TTL=241"""
        match = re.search(r' time=(.*) ms', log_line)
        return float(match.group(1)) if match else 0

    def analyze_latency_variations(self):
        """Analyze latency variations"""
        # if self.line_number <= self.start_step:
        #     return

        if self.current_latency - self.previous_latency > self.threshold * self.previous_latency \
                and self.drops_count == 0 and self.previous_latency > 0:
            self.statistics['drop'].append([])
            self.statistics['drop'][-1].append(self.previous_line)
            self.drops_count = self.lines_to_log_after_drop - 1

        if self.drops_count > 0:
            self.drops_count -= 1
            self.statistics['drop'][-1].append(self.current_line)

    def _get_logger(self, logger):
        return logger
